         filtered.to_set().contains(x) implies s.to_set().remove(key).contains(x)
     by {
         assert(filtered.contains(x));
         s.lemma_filter_contains_rev(pred, x);
         let idx = choose |idx: int| 0 <= idx < filtered.len() && filtered[idx] == x;

