 /// For a no-duplicate sequence containing key, filter(!=key) reduces length by exactly 1.
 proof fn lemma_filter_neq_len<K>(s: Seq<K>, key: K)
     requires
         s.no_duplicates(),
         s.contains(key),
     ensures
         s.filter(|k: K| k != key).len() == s.len() - 1,
