229. 
230.     if cache.capacity == 0 {
231.         // Zero-capacity: no-op.
232.     } else if cache.contents.dom().contains(key) {
233.         // Overwrite existing key.
234.         let result = cache.spec_put(key, value);
235.         let pred = |k: K| k != key;
236.         let filtered = cache.lru_order.filter(pred);
237.         let mru = cache.move_to_mru(key);
238. 
239.         // no_duplicates
240.         lemma_filter_preserves_no_dup(cache.lru_order, pred);
241.         assert(!filtered.contains(key)) by {
242.             if filtered.contains(key) {
243.                 let idx = choose |idx: int| 0 <= idx < filtered.len() && filtered[idx] == key;
244.                 cache.lru_order.lemma_filter_pred(pred, idx);
245.             }
246.         };
247.         lemma_push_preserves_no_dup(filtered, key);
248. 
249.         // to_set
250.         lemma_filter_neq_to_set(cache.lru_order, key);
251.         filtered.lemma_push_to_set_commute(key);
252.         assert(cache.lru_order.to_set().contains(key));
253.         assert(cache.lru_order.to_set().remove(key).insert(key) =~= cache.lru_order.to_set());
254.         assert(cache.contents.insert(key, value).dom() =~= cache.contents.dom());
255. 
256.         // len
257.         lemma_filter_neq_len(cache.lru_order, key);
258.         assert(cache.lru_order.contains(key));
259. 
260.     } else if cache.contents.dom().len() >= cache.capacity {
261.         // At capacity, new key: evict LRU victim.
262.         let result = cache.spec_put(key, value);
263.         let victim = cache.lru_order[0];
264.         let sub = cache.lru_order.subrange(1, cache.lru_order.len() as int);
